import React from 'react';
import { DigoAsset } from '@digo-org/digo-api';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Box } from '@react-three/drei';

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  override render() {
    const backgroundColor = this.globalParameters['background-color'] as string || '#1a1a1a';
    const showGrid = this.globalParameters['show-grid'] as boolean || false;
    const cameraX = this.globalParameters['camera-x'] as number || 5;
    const cameraY = this.globalParameters['camera-y'] as number || 5;
    const cameraZ = this.globalParameters['camera-z'] as number || 5;
    const ambientIntensity = this.globalParameters['ambient-intensity'] as number || 0.5;
    const directionalIntensity = this.globalParameters['directional-intensity'] as number || 1;

    return (
      <div style={{ width: '100%', height: '100%', background: backgroundColor }}>
        <Canvas camera={{ position: [cameraX, cameraY, cameraZ], fov: 50 }}>
          <ambientLight intensity={ambientIntensity} />
          <directionalLight position={[10, 10, 5]} intensity={directionalIntensity} />
          <pointLight position={[-10, -10, -5]} intensity={0.5} />

          {this.instances?.map((instance, index) => (
            <Box
              key={index}
              args={[
                instance['cube-size'] as number || 2,
                instance['cube-size'] as number || 2,
                instance['cube-size'] as number || 2
              ]}
              position={[
                instance['position-x'] as number || 0,
                instance['position-y'] as number || 0,
                instance['position-z'] as number || 0
              ]}
            >
              <meshStandardMaterial color={instance['cube-color'] as string || '#ff6b6b'} />
            </Box>
          ))}

          {showGrid && <gridHelper args={[10, 10]} />}

          <OrbitControls enableDamping dampingFactor={0.05} />
        </Canvas>
      </div>
    );
  }
}

